import{_ as a,o as s,c as i,a2 as n}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"AI 编辑的可靠性边界：生成、预览、采纳和保存","description":"从编辑器里的 AI 请求生命周期出发，梳理迟到响应、取消传播、结果完整性、HTML 容量与用户采纳之间的边界。","frontmatter":{"title":"AI 编辑的可靠性边界：生成、预览、采纳和保存","description":"从编辑器里的 AI 请求生命周期出发，梳理迟到响应、取消传播、结果完整性、HTML 容量与用户采纳之间的边界。"},"headers":[],"relativePath":"practice/notes-ai-editing.md","filePath":"practice/notes-ai-editing.md","lastUpdated":1792725069000}'),e={name:"practice/notes-ai-editing.md"};function p(l,t,d,h,r,k){return s(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="ai-编辑的可靠性边界-生成、预览、采纳和保存" tabindex="-1">AI 编辑的可靠性边界：生成、预览、采纳和保存 <a class="header-anchor" href="#ai-编辑的可靠性边界-生成、预览、采纳和保存" aria-label="Permalink to &quot;AI 编辑的可靠性边界：生成、预览、采纳和保存&quot;">​</a></h1><p>用户选中一段文字让 AI 改写，等了一会儿关掉弹窗，继续编辑另一段。旧请求随后返回，如果直接把结果写回编辑器，用户刚输入的内容就可能被覆盖。</p><p>另一个常见失败是：AI 结果已经完整生成，也能在预览里显示，但插入现有正文后超过保存容量。用户点了“采纳”，最终却存不下来。</p><p>这两类问题都不是换一个提示词就能解决的。<strong>生成成功、结果仍适用、用户采纳和持久保存，是四次不同的确认。</strong></p><blockquote><p>本文总结当前源码能证明的行为，示例均为通用重写。建议方案会单独标明；没有把本次只读检查写成业务测试结果。</p></blockquote><p>**2026-10-23 更新：**近期已提交的前后端改动补齐了主动取消、编辑目标校验和进程内并发准入。下文按新实现说明，不再把“关闭只忽略结果”当作当前状态。</p><h2 id="先给每个阶段一个明确结果" tabindex="-1">先给每个阶段一个明确结果 <a class="header-anchor" href="#先给每个阶段一个明确结果" aria-label="Permalink to &quot;先给每个阶段一个明确结果&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户选择操作与内容</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>提交生成任务 → 失败、超时或取消</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>校验并展示候选结果</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>用户采纳 → 修改编辑器、成为未保存内容</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>按原有保存流程提交 → 持久化成功或冲突</span></span></code></pre></div><p>当前 AI 服务端只返回候选结果，不直接写正文。选区编辑和辅助写作在用户采纳后修改编辑器，后续仍经过页面原有保存流程。</p><p>这个边界让用户可以放弃一次生成，也让保存冲突继续由已有机制处理。不能因为内容来自 AI，就绕开编辑会话或省略保存失败提示。</p><table tabindex="0"><thead><tr><th>阶段</th><th>可以告诉用户什么</th><th>还不能承诺什么</th></tr></thead><tbody><tr><td>生成完成</td><td>已获得候选结果</td><td>内容一定正确或适用于当前文档</td></tr><tr><td>预览完成</td><td>可以比较、复制或采纳</td><td>已改动正文</td></tr><tr><td>采纳完成</td><td>当前编辑器已更新</td><td>服务端已经保存</td></tr><tr><td>保存完成</td><td>本次提交已被服务端确认</td><td>用户此后新增的输入也已保存</td></tr></tbody></table><p>最后一种边界与普通编辑相同，详见<a href="/practice/notes-save-lifecycle">编辑会话与本地草稿</a>。</p><h2 id="当前实现-忽略已经过期的生成结果" tabindex="-1">当前实现：忽略已经过期的生成结果 <a class="header-anchor" href="#当前实现-忽略已经过期的生成结果" aria-label="Permalink to &quot;当前实现：忽略已经过期的生成结果&quot;">​</a></h2><p>前端为选区编辑和辅助写作分别维护请求序号。重新生成或关闭对应弹窗时，旧序号失效；响应返回后先核对序号，过期结果不进入预览。</p><p>它解决的是“这个响应还属于当前交互吗”，而不是判断模型答案好不好。</p><p>下面重新写一个最小示例，只演示结果失效机制：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createPreviewTask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">generate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> active </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ticket</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Symbol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;preview&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      active </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ticket</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> generate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (active </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ticket) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    dismiss</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      active </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这不是完整任务管理器：错误展示、loading 清理、网络取消和组件卸载都需要额外处理。它刻意只说明“过期结果不能更新当前界面”。</p><p>近期编辑器入口还会记录编辑器实例、文档快照、账号会话代次与原始选区。结果返回及用户采纳时再次核对目标，编辑器销毁、账号变化或正文变化后，旧结果不再应用。</p><p>这是较保守的快照策略：即使只改了文档另一处，也可能让旧候选失效。它没有实现自动重定位或将 AI 结果合并到变化后的文档；若需要更宽松的交互，仍须设计位置映射和冲突处理。</p><h2 id="关闭弹窗和取消上游是两件事" tabindex="-1">关闭弹窗和取消上游是两件事 <a class="header-anchor" href="#关闭弹窗和取消上游是两件事" aria-label="Permalink to &quot;关闭弹窗和取消上游是两件事&quot;">​</a></h2><p>当前编辑器在生成中关闭弹窗，会作废请求序号并调用 <code>AbortController.abort()</code>；信号经 AI 服务封装传给公共请求层，最终进入 fetch。离开、断网、会话失效和作用域清理也有相应取消或失效处理。</p><p>服务端另有取消机制：客户端响应连接异常关闭时，向上游请求传播取消信号。它监听响应连接，避免把正常请求体读取结束误判为任务取消。</p><p>因此，源码现在能追踪到“界面取消 → 客户端请求中止 → 响应连接断开时服务端传播取消”的链路。反向代理是否及时传递断连、上游是否立即停止计算或计费，仍需要部署环境与供应商协议的证据，不能仅凭本地代码作保证。</p><table tabindex="0"><thead><tr><th>取消层级</th><th>目的</th></tr></thead><tbody><tr><td>界面失效</td><td>不再展示或采纳这次结果</td></tr><tr><td>客户端请求中止</td><td>结束本次网络等待</td></tr><tr><td>服务端传播信号</td><td>尽量停止继续等待上游</td></tr><tr><td>上游实际停止</td><td>取决于上游协议与执行状态</td></tr></tbody></table><p><code>AbortController.abort()</code> 可以中止 fetch 及其响应体读取，但它不提供远端业务事务回滚保证；后者是必须另行设计的协议边界。<a href="https://developer.mozilla.org/en-US/docs/Web/API/AbortController/abort" target="_blank" rel="noreferrer">MDN AbortController.abort</a></p><p>当前实现同时保留网络取消和结果归属校验。取消与响应可能相邻发生，任何一层都不能单独替代另一层。</p><h2 id="超时覆盖整段等待-清理覆盖每个出口" tabindex="-1">超时覆盖整段等待，清理覆盖每个出口 <a class="header-anchor" href="#超时覆盖整段等待-清理覆盖每个出口" aria-label="Permalink to &quot;超时覆盖整段等待，清理覆盖每个出口&quot;">​</a></h2><p>当前模型调用集中在公共模块，调用方负责构造任务内容；连接错误、超时与部分上游错误在共同出口处理。</p><p>一次总超时应包含连接、等待响应和读取响应体。只给建立连接设置超时，不能限制模型长时间思考或响应体迟迟不结束。</p><p>当前实现会在结束时清理计时器和取消监听器。否则旧任务的计时器可能干扰后续工作，长期存在的监听器也会增加排查难度。</p><p>等待上限是项目的运行选择，不等于模型供应商对推理时长的承诺。浏览器、服务端和代理的限制需要协调，错误文案也应区分主动取消、超时与上游失败。</p><h2 id="并发容量和调用频率分开管理" tabindex="-1">并发容量和调用频率分开管理 <a class="header-anchor" href="#并发容量和调用频率分开管理" aria-label="Permalink to &quot;并发容量和调用频率分开管理&quot;">​</a></h2><p>近期服务端把几种生成动作统一接入准入模块，在完成内容校验、准备调用上游时占用资源：</p><table tabindex="0"><thead><tr><th>限制</th><th>解决什么问题</th><th>什么时候释放</th></tr></thead><tbody><tr><td>单账号在途任务</td><td>同一用户重复提交长任务</td><td>本次调用结束</td></tr><tr><td>单进程在途任务</td><td>多用户同时占满运行资源</td><td>本次调用结束</td></tr><tr><td>时间窗口调用次数</td><td>连续发起或取消造成高频调用</td><td>等待窗口自然过去</td></tr></tbody></table><p>当前拒绝超额请求，不在进程中无限排队；错误提供可区分的原因与重试等待时间。上游即使返回网关 HTML，繁忙和限流状态也有独立处理路径，不能全部转成“响应解析失败”。</p><p>占用后通过 <code>finally</code> 释放在途资源，释放函数本身幂等，防止重复清理把计数减错。已经发出的请求取消后仍计入时间窗口次数：归还执行槽位不代表抹去已经发生的调用。</p><p>这些计数仍在单进程内存里。多进程或多实例会各自计数，不能把它描述为全站共享配额。共享限额、持久任务队列和跨实例公平性仍是后续设计项。</p><h2 id="容量至少有四种单位" tabindex="-1">容量至少有四种单位 <a class="header-anchor" href="#容量至少有四种单位" aria-label="Permalink to &quot;容量至少有四种单位&quot;">​</a></h2><p>“内容不能超过某个长度”如果没有单位，前后端很容易各写出一种解释。</p><table tabindex="0"><thead><tr><th>边界</th><th>常见单位</th><th>应检查的对象</th></tr></thead><tbody><tr><td>HTTP 请求体</td><td>字节</td><td>编码后的整个请求</td></tr><tr><td>编辑器保存容量</td><td>字符串计数或字节</td><td>最终持久化正文，含标记和嵌入内容</td></tr><tr><td>模型上下文</td><td>tokens</td><td>提示词、用户内容及输出预算等上下文组成</td></tr><tr><td>文件上传</td><td>字节</td><td>独立资源本身</td></tr></tbody></table><p>JavaScript 的 <code>string.length</code> 计算 UTF-16 码元，不等于 UTF-8 字节，也不等于人眼看到的字符数，更不能直接充当 token 计数。</p><p>当前实现把应用 HTML 容量与已识别模型的容量配置分开：请求的原始 HTML 先受应用限制；模型端负责判断实际上下文是否超限；返回结果清洗后再检查应用容量。</p><p>这里的模型配置只代表项目读到的能力假设，不能直接推广到所有兼容服务。适配新模型时，应重新核对参数语义和完成原因。</p><h2 id="不要用截断把失败伪装成成功" tabindex="-1">不要用截断把失败伪装成成功 <a class="header-anchor" href="#不要用截断把失败伪装成成功" aria-label="Permalink to &quot;不要用截断把失败伪装成成功&quot;">​</a></h2><p>简单截取字符串尾部，可能丢掉用户最重要的背景；截取输出前半段，则可能留下未闭合结构或未写完的结论。</p><p>当前已识别模型的写作上下文不会再按旧字符阈值静默截尾；支持思考模式的模型调用路径会识别长度耗尽的结束原因，拒绝把已知不完整结果作为成功返回。</p><p>这个保护有明确适用范围：未知模型仍保留原有兼容限制，不能宣称所有供应商、所有模型都已具备同样的截断检测。</p><p>应用容量超限时，当前已识别模型路径会明确失败，而不是把清洗后的 HTML 截成一段返回。对于上游明确报告的上下文超限，也会提示缩小内容或拆分文档。</p><p>**建议：**把“缩短范围后重试”作为显式用户动作。需要自动分块时，应设计段落边界、上下文衔接和结果校验，而不是藏在字符串截断里。</p><h2 id="采纳前还要检查整篇文档" tabindex="-1">采纳前还要检查整篇文档 <a class="header-anchor" href="#采纳前还要检查整篇文档" aria-label="Permalink to &quot;采纳前还要检查整篇文档&quot;">​</a></h2><p>一段候选结果单独不超限，不代表追加后仍能保存；替换选区也要考虑被删内容与新内容的差额。</p><p>通用判断流程可以写成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当前文档 + 本次替换或插入操作</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>在临时文档上应用变更</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>按持久格式序列化并检查容量</span></span>
<span class="line"><span>        ├─ 超限 → 保留候选结果，提示缩小范围</span></span>
<span class="line"><span>        └─ 合法 → 允许采纳，再走正常保存</span></span></code></pre></div><p>这是进一步加强采纳体验的建议，不表示当前每个采纳入口都已实现临时文档预检查。服务端保存校验仍是最后一道边界，不能只依赖按钮状态。</p><p>模型输出也不是可信 HTML。当前结果会经过白名单清洗，但清洗不证明事实正确，也不替代编辑器自己的内容约束。格式与附件身份如何保存，见<a href="/practice/notes-rich-text-assets">富文本与附件生命周期</a>。</p><h2 id="失败案例与验证建议" tabindex="-1">失败案例与验证建议 <a class="header-anchor" href="#失败案例与验证建议" aria-label="Permalink to &quot;失败案例与验证建议&quot;">​</a></h2><p>下面场景适合在隔离环境配合可控响应验证。本次整理没有调用真实模型执行这些测试。</p><table tabindex="0"><thead><tr><th>场景</th><th>应观察的结果</th></tr></thead><tbody><tr><td>先发甲请求，再发乙请求，甲最后返回</td><td>甲不能覆盖乙的预览</td></tr><tr><td>生成期间关闭弹窗</td><td>不改正文，迟到结果不重新打开旧预览</td></tr><tr><td>页面连接断开</td><td>服务端取消等待，计时器和监听器得到清理</td></tr><tr><td>同一账号或进程并发超过限制</td><td>明确拒绝，不无限排队；已有任务不受误释放影响</td></tr><tr><td>请求取消后立刻再发</td><td>在途资源可释放，时间窗口调用记录仍保留</td></tr><tr><td>上游明确返回长度耗尽</td><td>对支持该识别的路径，不展示为完整成功</td></tr><tr><td>返回 HTML 含不允许的结构</td><td>清洗后检查可展示内容与容量</td></tr><tr><td>候选片段合法，追加后全文超限</td><td>保留用户原文与候选结果，明确说明无法保存</td></tr><tr><td>采纳后发生保存冲突</td><td>使用正常冲突流程，不绕过版本校验</td></tr><tr><td>代理先于应用超时</td><td>错误可见，不能把无响应当作已保存</td></tr></tbody></table><p>验证时同时观察界面状态、编辑器内容和持久数据。只看“AI 请求返回成功”，不足以证明这次编辑可靠完成。</p><h2 id="接下来读什么" tabindex="-1">接下来读什么 <a class="header-anchor" href="#接下来读什么" aria-label="Permalink to &quot;接下来读什么&quot;">​</a></h2><ul><li><a href="/practice/notes-architecture">笔记应用开发实践总览</a>：理解 AI 能力在整个系统里的位置。</li><li><a href="/practice/notes-sync-consistency">快照同步与并发冲突</a>：采纳后的内容怎样接受版本保护。</li><li><a href="/practice/notes-release-recovery">懒加载与发布恢复</a>：长时间打开的编辑页面怎样应对发布变化。</li></ul>`,62)])])}const E=a(e,[["render",p]]);export{c as __pageData,E as default};
